import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a math contest, let a be a positive integer (assume 2\\cos a + \\cos(3a) \\neq 0) and let x_1, x_2, \\ldots, x_{chain_length} be positive real numbers. Define cyclic indexing so that x_{i+1} means x_{1} when i = {chain_length}. Consider the expression\n\nE = \\frac{{lambda_factor}\\,\\big(16(\\cos a)^5 - \\cos(5a)\\big)}{2\\cos a + \\cos(3a)} \\cdot \\frac{{weight}\\,\\sum_{i=1}^{ {chain_length} } x_i^{ {k_exponent} }\\,x_{i+1}}{\\sum_{i=1}^{ {chain_length} } x_i^{ {k_exponent} + 1 }}.\n\nFind the maximum value of E over all choices of the positive reals x_1,\\ldots,x_{chain_length} (depending only on the parameters and not on a).'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# choose parameters ensuring non-triviality and well-posedness
chain_length = rng.randint(3, 8)          # at least 3 to make cyclic structure meaningful
k_exponent = rng.randint(2, 5)             # k >= 2 for genuine Young application beyond trivial linear case
lambda_factor = rng.randint(2, 9)          # nontrivial scaling of trig ratio
weight = rng.randint(2, 9)                 # nontrivial uniform weight
return {
    'chain_length': chain_length,
    'k_exponent': k_exponent,
    'lambda_factor': lambda_factor,
    'weight': weight
}

    def verifier(assign):
# Validate presence and ranges
try:
    chain_length = int(assign.get('chain_length'))
    k_exponent = int(assign.get('k_exponent'))
    lambda_factor = int(assign.get('lambda_factor'))
    weight = int(assign.get('weight'))
except Exception:
    # invalid typing
    return (False, None)
# domain checks to enforce non-triviality and avoid degenerate cases
if not (3 <= chain_length <= 100):
    # chain must be meaningful
    return (False, None)
if not (2 <= k_exponent <= 50):
    return (False, None)
if not (2 <= lambda_factor <= 10**6):
    return (False, None)
if not (2 <= weight <= 10**6):
    return (False, None)
# Mathematical recomputation:
# Trig ratio: For all real a with 2 cos a + cos 3a != 0,
# (16 cos^5 a - cos 5a)/(2 cos a + cos 3a) = 5, by Chebyshev identity for cos(5a).
# Hence the trig factor equals 5 * lambda_factor.
trig_factor = 5 * lambda_factor
# Algebraic factor maximum: For positive reals x_i on a cyclic chain,
# sum x_i^k x_{i+1} / sum x_i^{k+1} <= 1 by Young with p=(k+1)/k, q=k+1,
# and equality at x_1=...=x_{chain_length}. With uniform weight, the maximum scales by 'weight'.
algebraic_max = weight
final_val = trig_factor * algebraic_max
answer = f"### The final answer is: $\\boxed{{{final_val}}}$"
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

